            { "squareTreeSprawling", p => { p.GridType = GridType.Square; p.LoopChance = 0f; p.LayoutBias = 1f; p.TargetRoomCount = 30; } },
            { "squareThickHalfCeilings", p => { p.GridType = GridType.Square; p.WallThickness = 1f; p.AddCeiling = true; p.CeilingChance = 0.5f; p.MinCellsPerRoom = 2; p.MaxCellsPerRoom = 8; p.TargetRoomCount = 20; } },
            { "squareThickFullDoors", p => { p.GridType = GridType.Square; p.WallThickness = 2f; p.DoorHeight = 3f; p.MinCellsPerRoom = 3; p.MaxCellsPerRoom = 9; p.TargetRoomCount = 20; } },
            { "triangleDefault", p => { p.GridType = GridType.Triangle; } },
            { "triangleLarge", p => { p.GridType = GridType.Triangle; p.MinCellsPerRoom = 4; p.MaxCellsPerRoom = 12; p.TargetRoomCount = 25; } },
            { "triangleTreeSprawling", p => { p.GridType = GridType.Triangle; p.LoopChance = 0f; p.LayoutBias = 1f; p.TargetRoomCount = 30; } },
            { "triangleThickHalfCeilings", p => { p.GridType = GridType.Triangle; p.WallThickness = 1f; p.AddCeiling = true; p.CeilingChance = 0.5f; p.MinCellsPerRoom = 2; p.MaxCellsPerRoom = 10; p.TargetRoomCount = 20; } },
